fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since both arrays have the same length, we can safely zip them together
    // and perform bitwise AND on each pair of elements.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}